import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{name:string,params:any,trigger:string}>} cinematicPrimitives
 * @property {string} [imageUrl]
 * @property {Array<{text:string,role:string,typography?:{fontSize?:number}}>} [textContent]
 * @property {Object} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // Apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name]?.(group, prim.params);
      if (handler) primitiveHandles.push(handler);
    }
  }

  // Load texture if imageUrl provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Atlas region – using full texture (no offset) as spec gives region but we assume full
      const region = { x: 0, y: 0, w: 512, h: 320 };
      const aspect = region.w / region.h;

      const geometry = new PlaneGeometry(aspect, 1);
      // UV transformation to map the region (if needed)
      const uvNode = uv()
        .mul(vec2(region.w / tex.image.width, region.h / tex.image.height))
        .add(vec2(region.x / tex.image.width, region.y / tex.image.height));

      const material = new MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        depthWrite: false,
        uv: uvNode,
      });

      const mesh = new Mesh(geometry, material);
      mesh.renderOrder = 1; // ensure it renders over backdrop if any
      group.add(mesh);

      // Billboard update handler (align to camera)
      group.userData.handlers = group.userData.handlers || {};
      group.userData.handlers.update = (delta, time) => {
        if (ctx.camera) {
          group.quaternion.copy(ctx.camera.quaternion);
        }
      };
    });
  }

  // Attach cleanup
  group.userData.cleanup = () => {
    // Dispose primitives
    for (const h of primitiveHandles) {
      if (h.cleanup) h.cleanup();
    }
    // Dispose meshes and materials
    group.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
    // Kill any GSAP timelines (none in this node but safe)
    if (gsap && gsap.globalTimeline) {
      gsap.globalTimeline.clear();
    }
  };

  return group;
}
